using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;using System.Linq;
[InitializeOnLoad]public static class TerracedWindowEffects {
 static TerracedWindowEffects(){EditorApplication.delayCall+=Run;}
 static void Run(){const string e="Evidence/terraced-village-20261030/";if(EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists(e+"built.txt")||File.Exists(e+"window-effects.txt"))return;var scene=EditorSceneManager.GetActiveScene();if(!scene.name.Contains("TerracedInteriors"))return;int count=0;foreach(var light in Object.FindObjectsOfType<Light>().Where(l=>l.name=="Interior window outward spill")){light.intensity=7;light.range=9;var n=light.transform.forward;n.y=0;n.Normalize();light.transform.rotation=Quaternion.LookRotation(n+Vector3.down*.65f);var volume=light.GetComponent<VolumetricAdditionalLight>();if(!volume)volume=light.gameObject.AddComponent<VolumetricAdditionalLight>();volume.Scattering=.9f;volume.Anisotropy=.15f;volume.Radius=.25f;var fog=light.GetComponent<SettlementFogLight>();fog.innerRadius=.7f;fog.outerRadius=3.5f;fog.minimumDensity=.22f;fog.referenceIntensity=7;count++;}
 var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Demo/Environment/TerracedVillage/AmberWindow.mat");mat.SetColor("_EmissionColor",new Color(4.8f,2.25f,.57f));EditorUtility.SetDirty(mat);var manager=Object.FindObjectOfType<SettlementFogManager>();manager.lights=Object.FindObjectsOfType<SettlementFogLight>(true).Where(f=>f.source&&f.source.enabled).ToArray();EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText(e+"window-effects.txt","windows="+count+" VolumetricAdditionalLight scattering=.9 anisotropy=.15 radius=.25; spot intensity=7 range=9; SettlementFogLight inner=.7 outer=3.5 minDensity=.22 reference=7; emissive=(4.8,2.25,.57); existing Bloom+fog profiles preserved.\n");}
}
